static Node *toml_node(toml_datum_t d);
static Node *toml_table(toml_datum_t d) { Node *n=node(1,NULL,0,NULL,0);for(int i=0;i<d.u.tab.size;i++){Node *pair=node(1,NULL,0,NULL,0);add(pair,node(0,d.u.tab.key[i],(size_t)d.u.tab.len[i],NULL,0));add(pair,toml_node(d.u.tab.value[i]));add(n,pair);}return n; }
static Node *marker(const char *s) { if(!strncmp(s,"__ZCFC_SEXP_",12)){const char *p=s+12;size_t z=strlen(p);if(z<2||strcmp(p+z-2,"__"))die("corrupt @sexp marker");Buf b={0};for(size_t i=0;i<z-2;i+=2){int a=hx(p[i]),c=hx(p[i+1]);if(a<0||c<0)die("corrupt @sexp marker");ch(&b,(a<<4)|c);}Parser q={(unsigned char*)b.p,b.n,0,0};Node *n=sexp_read(&q);if(q.p!=q.n)die("bad @sexp payload");free(b.p);return n;}if(!strncmp(s,"__ZCFC_BIN_",11)){const char *p=s+11;size_t z=strlen(p);if(z<2||strcmp(p+z-2,"__"))die("corrupt binary marker");Buf b={0};for(size_t i=0;i<z-2;i+=2){int a=hx(p[i]),c=hx(p[i+1]);if(a<0||c<0)die("corrupt binary marker");ch(&b,(a<<4)|c);}Node *n=node(0,b.p,b.n,NULL,0);free(b.p);return n;}if(!strncmp(s,"__ZCFC_TYPED_",13)){const char *p=s+13,*u=strchr(p,'_');if(!u)die("corrupt typed marker");char *h=strndup(p,(size_t)(u-p));p=u+1;size_t z=strlen(p);if(z<2||strcmp(p+z-2,"__"))die("corrupt typed marker");Buf b={0};for(size_t i=0;i<z-2;i+=2){int a=hx(p[i]),c=hx(p[i+1]);if(a<0||c<0)die("corrupt typed marker");ch(&b,(a<<4)|c);}Node *n=node(0,NULL,0,NULL,0);typed(n,h,(unsigned char*)b.p,b.n);free(h);free(b.p);return n;}return NULL; }
static Node *toml_node(toml_datum_t d) { char tmp[128];switch(d.type){case TOML_TABLE:return toml_table(d);case TOML_ARRAY:{Node *n=node(1,NULL,0,NULL,0);for(int i=0;i<d.u.arr.size;i++)add(n,toml_node(d.u.arr.elem[i]));return n;}case TOML_STRING:{Node *m=marker(d.u.str.ptr);return m?m:node(0,d.u.str.ptr,(size_t)d.u.str.len,NULL,0);}case TOML_INT64:{Node *n=node(0,NULL,0,NULL,0);uint64_t v=(uint64_t)d.u.int64;le(n,v,8,"i64");return n;}case TOML_FP64:{Node *n=node(0,NULL,0,NULL,0);uint64_t v;memcpy(&v,&d.u.fp64,8);le(n,v,8,"f64");return n;}case TOML_BOOLEAN:{Node *n=node(0,NULL,0,NULL,0);le(n,d.u.boolean?1:0,1,"bool");return n;}case TOML_DATE:{int z=snprintf(tmp,sizeof(tmp),"%04d-%02d-%02d",d.u.ts.year,d.u.ts.month,d.u.ts.day);return node(0,tmp,(size_t)z,"iso8601",7);}case TOML_TIME:{int z=snprintf(tmp,sizeof(tmp),"%02d:%02d:%02d.%06d",d.u.ts.hour,d.u.ts.minute,d.u.ts.second,d.u.ts.usec);return node(0,tmp,(size_t)z,"iso8601",7);}case TOML_DATETIME:case TOML_DATETIMETZ:{int z=snprintf(tmp,sizeof(tmp),"%04d-%02d-%02dT%02d:%02d:%02d.%06d",d.u.ts.year,d.u.ts.month,d.u.ts.day,d.u.ts.hour,d.u.ts.minute,d.u.ts.second,d.u.ts.usec);Node *n=node(0,tmp,(size_t)z,"iso8601",7);return n;}default:die("unsupported TOML datum");}return NULL; }
static unsigned char *readfile(const char *f,size_t *n) { FILE *fp=fopen(f,"rb");if(!fp){perror(f);exit(1);}if(fseek(fp,0,SEEK_END)||(*n=(size_t)ftell(fp),fseek(fp,0,SEEK_SET)))die("cannot size input");unsigned char *p=xmalloc(*n+1);if(fread(p,1,*n,fp)!=*n)die("cannot read input");p[*n]=0;fclose(fp);return p; }
static void writefile(const char *f,Buf *b) { FILE *fp=fopen(f,"wb");if(!fp){perror(f);exit(1);}if(fwrite(b->p,1,b->n,fp)!=b->n)die("write failed");if(fclose(fp))die("close failed"); }
static Node *parse_ccb(const unsigned char *s,size_t n) { Parser p={s,n,0,0};Node *r=sexp_read(&p);if(p.p!=n)die("trailing CSEXPs data");return r; }
static void usage(void) { puts("zcfc build <input.toml|input.rtm> -o <output.ccb> [--emit-atm <output.rtm>]\nzcfc dump <input.ccb>\nzcfc fmt <input.rtm>"); }
int main(int argc,char **argv) { if(argc<3){usage();return 2;}if(!strcmp(argv[1],"fmt")){size_t n;unsigned char *s=readfile(argv[2],&n);Node *r=rtm_parse(s,n);Buf b={0};rtm_print(&b,r,0);ch(&b,'\n');fwrite(b.p,1,b.n,stdout);free(b.p);free_node(r);free(s);return 0;}if(!strcmp(argv[1],"dump")){size_t n;unsigned char *s=readfile(argv[2],&n);Node *r=parse_ccb(s,n);Buf b={0};rtm_print(&b,r,0);ch(&b,'\n');fwrite(b.p,1,b.n,stdout);free(b.p);free_node(r);free(s);return 0;}if(!strcmp(argv[1],"build")){if(argc<5)die("build requires -o output");const char *in=argv[2],*out=NULL,*atm=NULL;for(int i=3;i<argc;i++){if(!strcmp(argv[i],"-o")&&i+1<argc)out=argv[++i];else if(!strcmp(argv[i],"--emit-atm")&&i+1<argc)atm=argv[++i];else die("unknown build option");}if(!out)die("missing -o output");size_t n;unsigned char *src=readfile(in,&n);Node *root=NULL;if(strstr(in,".rtm")){root=rtm_parse(src,n);}else{Buf pre=preprocess(src,n);toml_result_t tr=toml_parse(pre.p,(int)pre.n);if(!tr.ok){fprintf(stderr,"zcfc: TOML: %s\n",tr.errmsg);return 1;}root=toml_table(tr.toptab);toml_free(tr);free(pre.p);}Buf ccb={0};sexp_write(&ccb,root);writefile(out,&ccb);if(atm){Buf a={0};rtm_print(&a,root,0);ch(&a,'\n');writefile(atm,&a);free(a.p);}free(ccb.p);free_node(root);free(src);return 0;}usage();return 2; }
